CREATE TABLE tbl(a,b,c,d); CREATE TABLE log(a); CREATE TABLE result(seq INTEGER PRIMARY KEY,v); INSERT INTO log VALUES(0); CREATE TRIGGER t1 BEFORE INSERT ON tbl WHEN new.a>20 BEGIN UPDATE log SET a=a+1; END; CREATE TRIGGER t2 BEFORE INSERT ON tbl WHEN (SELECT count(*) FROM tbl)=0 BEGIN UPDATE log SET a=a+1; END;